using System;using System.Collections.Generic;
static class OccupationCode {
public static byte[] Clear(long slot,long state,long province,uint identity,uint occupant,uint title,long result,long api,bool dryRun){long dry=dryRun?1:0;string hex="";var b=new byte[hex.Length/2];for(int i=0;i<b.Length;i++)b[i]=Convert.ToByte(hex.Substring(i*2,2),16);foreach(var p in new Dictionary<long,long>{{1311761354012491776L,slot},{1311761354013610257L,state},{1311761354014728738L,province},{1311761354015847219L,identity},{1311761354016965700L,occupant},{1311761354018084181L,title},{1311761354019202662L,result},{1311761354020321143L,api},{1311761354021439624L,dry}}){var old=BitConverter.GetBytes(p.Key);var next=BitConverter.GetBytes(p.Value);for(int i=0;i<=b.Length-8;i++){bool match=true;for(int j=0;j<8;j++)if(b[i+j]!=old[j]){match=false;break;}if(match){Array.Copy(next,0,b,i,8);i+=7;}}}return b;}
}
